import ast,base64,hashlib,json
s=base64.b64decode('').decode('utf-8')
assert hashlib.sha256(s.encode()).hexdigest()=='5144d2f61418f16966439f9563615f23a2859c0401e90b0d7d8187f109821eeb'
t=ast.parse(s,filename='mac_launcher.py')
compile(t,'mac_launcher.py','exec')
print(json.dumps({'file':'mac_launcher.py','bytes':len(s.encode()),'sha256':hashlib.sha256(s.encode()).hexdigest(),'ast_and_compile_only':True,'module_executed':False,'host_calls':0,'syntax':'passed'},sort_keys=True))
